NOTA_MIGRADA = 'Última renta (migrada)'  # written by migration 0022 from Inmueble.ultima_renta


def a_regulacion_alquiler(apps, schema_editor):
    """Give each monthly offer a regulation record with what its listing carried.

    The index range is copied. The last rent that migration 0022 turned into a history row becomes a
    declared `con_renta` (its end date is unknown); that helper row is removed from the price log.
    `situacion_5_anios` was free text and `actualizacion_renta` a listing text: neither is migrated.
    """
    Oferta = apps.get_model('base', 'InmuebleModalidad')
    Regulacion = apps.get_model('base', 'RegulacionAlquiler')
    Historial = apps.get_model('base', 'HistorialPrecio')
    for oferta in Oferta.objects.filter(modalidad__unidad_precio='mensual').select_related('inmueble'):
        inmueble = oferta.inmueble
        migrada = Historial.objects.filter(
            inmueble_id=oferta.inmueble_id, modalidad_id=oferta.modalidad_id, nota=NOTA_MIGRADA
        ).first()
        tiene_indice = inmueble.indice_referencia_min is not None or inmueble.indice_referencia_max is not None
        if not (tiene_indice or migrada):
            continue
        Regulacion.objects.create(
            oferta=oferta,
            indice_referencia_min=inmueble.indice_referencia_min,
            indice_referencia_max=inmueble.indice_referencia_max,
            renta_previa='con_renta' if migrada else 'desconocida',
            ultima_renta=migrada.importe if migrada else None,
        )
    Historial.objects.filter(nota=NOTA_MIGRADA).delete()


def de_vuelta_a_inmueble(apps, schema_editor):
    """Back to the listing columns: the index range of its first monthly offer that has one."""
    Regulacion = apps.get_model('base', 'RegulacionAlquiler')
    Inmueble = apps.get_model('base', 'Inmueble')
    hechos = set()
    for regulacion in Regulacion.objects.select_related('oferta').order_by('oferta__modalidad__orden', 'id'):
        inmueble_id = regulacion.oferta.inmueble_id
        if inmueble_id in hechos:
            continue
        hechos.add(inmueble_id)
        Inmueble.objects.filter(pk=inmueble_id).update(
            indice_referencia_min=regulacion.indice_referencia_min,
            indice_referencia_max=regulacion.indice_referencia_max,
        )


